// ResolveHubURL returns the hub URL from flag, config, or default.
func ResolveHubURL(flagURL string, cfg *VaultConfig) string {
	if flagURL != "" {
		return flagURL
	}
	if cfg != nil && cfg.HubURL != "" {
		return cfg.HubURL
	}
	return "http://127.0.0.1:8080"
}

